INSERT OR REPLACE INTO products (id, brand, model, category, sub, description, usage, strengths, limitations, specs, manufacturer_url, sources, image, image_credit, checked_at, editorial_refs) VALUES ('allen-heath-sq5', 'Allen & Heath', 'SQ-5', 'consoles', 'Numériques', 'Console numérique compacte à moteur 96 kHz pour le mixage, les retours et l’enregistrement multipiste.', 'Régie live, répétition et captation avec routage et mémoires de scènes.', '["48 canaux de traitement","Interface USB 32 × 32 et extension SLink"]', '["Les 48 canaux ne correspondent pas à 48 prises micro locales","Ne pas confondre SQ-5 et nouvelle SQ5+"]', '{"Architecture":"Numérique · 96 kHz","Canaux":"48 traitements · 16 préamplis micro locaux + talkback"}', 'https://www.allen-heath.com/hardware/sq/', '[{"label":"Allen & Heath — gamme SQ","url":"https://www.allen-heath.com/hardware/sq/"},{"label":"Allen & Heath — guide de prise en main","url":"https://support.allen-heath.com/hc/en-gb/articles/41332471203985-SQ-5-SQ-6-SQ-7-Getting-Started-Guide"}]', '/assets/products/allen-heath-sq5.jpg', 'Allen & Heath', '2026-10-26', '[]');
INSERT OR REPLACE INTO products (id, brand, model, category, sub, description, usage, strengths, limitations, specs, manufacturer_url, sources, image, image_credit, checked_at, editorial_refs) VALUES ('behringer-x32', 'Behringer', 'X32', 'consoles', 'Numériques', 'Console numérique complète avec 32 préamplis programmables, faders motorisés et interface audio multicanal.', 'Mixer un groupe, gérer les retours et capturer les pistes dans une station audio.', '["32 préamplis locaux et 25 faders motorisés","Routage et traitements intégrés adaptés à plusieurs usages"]', '["Surface plus encombrante que les versions Compact et Rack","Architecture limitée aux fréquences de base 44,1 / 48 kHz"]', '{"Architecture":"Numérique · 44,1 / 48 kHz","Canaux":"40 entrées de traitement · 32 préamplis"}', 'https://behringer.com/en/products/0603-ACE', '[{"label":"Behringer — X32","url":"https://behringer.com/en/products/0603-ACE"},{"label":"Sound On Sound — essai X32","url":"https://www.soundonsound.com/reviews/behringer-x32"}]', '/assets/products/behringer-x32.jpg', 'Behringer', '2026-10-26', '[]');
INSERT OR REPLACE INTO products (id, brand, model, category, sub, description, usage, strengths, limitations, specs, manufacturer_url, sources, image, image_credit, checked_at, editorial_refs) VALUES ('qsc-touchmix16', 'QSC', 'TouchMix-16', 'consoles', 'Numériques', 'Mixeur numérique compact à écran tactile, avec traitements de canaux et enregistrement direct sur support USB.', 'Petites formations et captations mobiles lorsque l’encombrement est prioritaire.', '["16 entrées micro/ligne et deux entrées stéréo","Enregistrement des entrées et du mix stéréo sans ordinateur"]', '["Commandes tactiles plutôt qu’une banque de faders physiques","Support USB compatible à prévoir pour l’enregistrement"]', '{"Architecture":"Numérique · écran tactile","Canaux":"20 entrées analogiques + lecture USB stéréo"}', 'https://www.qscaudio.com/index.php?id=134', '[{"label":"QSC — caractéristiques TouchMix-16","url":"https://www.qscaudio.com/index.php?id=134"},{"label":"QSC — capacité d’enregistrement","url":"https://support.qscaudio.com/faq-%7C-what-size-hard-drive-do-i-need-for-recording-on-my-touchmix"}]', '/assets/products/qsc-touchmix16.png', 'QSC · visuel produit distribué par Sonolens', '2026-10-26', '[]');
INSERT OR REPLACE INTO products (id, brand, model, category, sub, description, usage, strengths, limitations, specs, manufacturer_url, sources, image, image_credit, checked_at, editorial_refs) VALUES ('genelec-unio-prm', 'Genelec', 'UNIO PRM', 'monitoring', 'Contrôleurs', 'Ensemble d’écoute personnelle associant le contrôleur 9320A et le casque 8550A calibré en usine.', 'Maintenir une chaîne d’écoute cohérente entre casque et système de monitoring Genelec SAM.', '["Casque et contrôleur conçus pour fonctionner ensemble","Intégration de GLM et connexion USB"]', '["Fonctions avancées liées à l’écosystème Genelec","Aural ID et ses conditions de compatibilité sont à vérifier séparément"]', '{"Architecture":"Contrôleur 9320A + casque 8550A","Haut-parleur":"Casque de référence","Connexions":"USB · analogique · AES/EBU via 9320A","Conditionnement":"Système PRM · contenu à confirmer auprès du revendeur"}', 'https://www.genelec.com/unio', '[{"label":"Genelec — système UNIO PRM","url":"https://www.genelec.com/unio"},{"label":"Genelec — distribution PRM","url":"https://support.genelec.com/hc/en-us/articles/26520326220178-Where-can-I-purchase-the-Genelec-UNIO-PRM-system"}]', '/assets/products/genelec-unio-prm.jpg', 'Genelec', '2026-10-26', '[]');
INSERT OR REPLACE INTO products (id, brand, model, category, sub, description, usage, strengths, limitations, specs, manufacturer_url, sources, image, image_credit, checked_at, editorial_refs) VALUES ('neumann-tlm-102', 'Neumann', 'TLM 102', 'microphones', 'Condensateur', 'Microphone cardioïde à grande membrane, compact, pour les voix et les instruments acoustiques.', 'Prise de voix, guitare acoustique et sources puissantes dans un espace dont l’acoustique est maîtrisée.', '["Format compact, facile à placer.","Niveau maximal annoncé de 144 dB SPL ; légère mise en avant de l’aigu."]', '["Directivité cardioïde fixe, sans filtre ni atténuateur commutables.","Prévoir une alimentation 48 V ; suspension incluse uniquement selon le pack."]', '{"Type":"Condensateur à grande membrane","Directivité":"Cardioïde","Connectique":"XLR 3 broches · P48","Bruit propre":"12 dB-A","SPL maximal":"144 dB (THD 0,5 %)"}', 'https://www.neumann.com/en-en/products/microphones/tlm-102', '[{"label":"Neumann — données et accessoires","url":"https://www.neumann.com/en-en/products/microphones/tlm-102"},{"label":"Sound On Sound — essai TLM102","url":"https://www.soundonsound.com/reviews/neumann-tlm102"},{"label":"MusicRadar — essai TLM 102","url":"https://www.musicradar.com/reviews/neumann-tlm-102-review"}]', '/assets/products/neumann-tlm-102.webp', 'Neumann', '2026-10-26', '[]');
INSERT OR REPLACE INTO products (id, brand, model, category, sub, description, usage, strengths, limitations, specs, manufacturer_url, sources, image, image_credit, checked_at, editorial_refs) VALUES ('rode-nt1-signature', 'RØDE', 'NT1 Signature Series', 'microphones', 'Condensateur', 'Microphone XLR à grande membrane, livré avec suspension, filtre anti-pop et câble.', 'Enregistrement de voix ou d’instruments acoustiques avec une interface équipée d’une alimentation fantôme.', '["Bruit propre annoncé de 4 dBA.","Accessoires de prise de voix fournis."]', '["Version XLR uniquement : ne pas confondre avec le NT1 5th Generation USB.","Cardioïde fixe ; l’acoustique de la pièce reste déterminante."]', '{"Type":"Condensateur à grande membrane","Directivité":"Cardioïde","Connectique":"XLR 3 broches · P48","Bruit propre":"4 dBA","SPL maximal":"142 dB"}', 'https://rode.com/en-au/products/nt1-signature-series', '[{"label":"RØDE — NT1 Signature Series","url":"https://rode.com/en-au/products/nt1-signature-series"},{"label":"RØDE — fiche technique","url":"https://edge.rode.com/pdf/products/1362/NT1%20Signature%20Series_Datasheet_FA.pdf"},{"label":"MusicRadar — sélection microphones XLR","url":"https://www.musicradar.com/news/best-xlr-microphones"}]', '/assets/products/rode-nt1-signature.png', 'RØDE', '2026-10-26', '[]');
INSERT OR REPLACE INTO products (id, brand, model, category, sub, description, usage, strengths, limitations, specs, manufacturer_url, sources, image, image_credit, checked_at, editorial_refs) VALUES ('electro-voice-re20', 'Electro-Voice', 'RE20', 'microphones', 'Dynamiques', 'Microphone dynamique cardioïde pour la voix, le broadcast et les instruments, avec conception Variable-D.', 'Voix parlée, podcast, ampli basse ou grosse caisse ; adapté aux prises rapprochées.', '["Conception limitant l’effet de proximité.","Filtre anti-pop interne et commutateur de correction du grave."]', '["Poids de 737 g : prévoir un pied ou bras adapté.","Sensibilité de 1,5 mV/Pa : dimensionner le gain du préampli pour les voix faibles."]', '{"Type":"Dynamique","Directivité":"Cardioïde","Connectique":"XLR 3 broches","Réponse annoncée":"45 Hz–18 kHz","Impédance":"150 Ω"}', 'https://www.electrovoice.com/product/re20', '[{"label":"Electro-Voice — RE20","url":"https://www.electrovoice.com/product/re20"},{"label":"Electro-Voice — spécifications","url":"https://products.electrovoice.com/emea/en/re20"},{"label":"MusicRadar — microphones pour l’enregistrement","url":"https://www.musicradar.com/news/the-best-microphones-for-recording"}]', '/assets/products/electro-voice-re20.png', 'Electro-Voice', '2026-10-26', '[]');
