INSERT OR REPLACE INTO products (id, brand, model, category, sub, description, usage, strengths, limitations, specs, manufacturer_url, sources, image, image_credit, checked_at, editorial_refs) VALUES ('nugen-vislm-3', 'NUGEN Audio', 'VisLM 3', 'logiciels', 'Utilitaires', 'Plug-in de mesure du niveau sonore pour la postproduction et la diffusion.', 'Contrôle du loudness, des stems et des livrables audio', '["Vue commune de plusieurs stems et notes horodatées selon NUGEN","Export de rapports de contrôle qualité selon NUGEN"]', '["Toutes les fonctions ReMEM nécessitent un timecode fourni par le logiciel hôte"]', '{"Formats":"AAX, VST3, AU et AudioSuite · 64 bits","Système":"macOS 11 ou Windows 10 minimum selon NUGEN","Mesures":"Loudness et True Peak · historique ReMEM"}', 'https://nugenaudio.com/vislm/', '[{"label":"Caractéristiques et prérequis — NUGEN Audio","url":"https://nugenaudio.com/vislm/"},{"label":"Annonce du 29 octobre 2026 — Mix Online","url":"https://www.mixonline.com/technology/news-products/nugen-audio-launches-next-gen-vislm-3"}]', '/assets/products/nugen-vislm-3.jpg', 'NUGEN Audio', '2026-11-04', '[{"title":"VisLM 3 : suivre le niveau sonore de plusieurs stems","url":"/actualites/#nugen-vislm-3-2026"}]');
INSERT OR REPLACE INTO products (id, brand, model, category, sub, description, usage, strengths, limitations, specs, manufacturer_url, sources, image, image_credit, checked_at, editorial_refs) VALUES ('izotope-photon', 'iZotope', 'Photon', 'logiciels', 'Restauration', 'Application de séparation de sources et de nettoyage audio par modèles locaux.', 'Séparation de stems et restauration de dialogues', '["Traitement local sans envoi des fichiers audio selon iZotope","Séparation de jusqu’à six intervenants selon le fabricant"]', '["Mac Intel non pris en charge","GPU avec 4 Go de VRAM minimum sous Windows ; hôte ARA2 nécessaire pour le plug-in"]', '{"Format":"Application autonome et plug-in ARA2","Traitement":"12 modèles · calcul local sur GPU","Système":"macOS 14 avec Apple silicon ; Windows 10 64 bits minimum"}', 'https://www.izotope.com/products/photon/', '[{"label":"Caractéristiques et prérequis — iZotope","url":"https://www.izotope.com/products/photon/"},{"label":"Présentation officielle du 3 novembre 2026","url":"https://www.izotope.com/community/blog/introducing-photon"}]', '/assets/products/izotope-photon.png', 'iZotope', '2026-11-05', '[{"title":"Photon : séparer les sources et nettoyer les dialogues en local","url":"/actualites/#izotope-photon-2026"}]');
INSERT OR REPLACE INTO products (id, brand, model, category, sub, description, usage, strengths, limitations, specs, manufacturer_url, sources, image, image_credit, checked_at, editorial_refs) VALUES ('placid-audio-carbonphone-ru-80', 'Placid Audio', 'Carbonphone RU-80', 'microphones', 'Carbone', 'Microphone à granules de carbone pour des prises volontairement colorées.', 'Effets lo-fi sur voix, guitare et batterie', '["Texture saturée appréciée par Rob Tavaglione dans Mix Online","Sortie symétrique par transformateur selon Placid Audio"]', '["Réponse difficile sur les sons très faibles selon Mix Online","Distorsion intrinsèque : prise colorée plutôt que restitution neutre"]', '{"Type":"Capsule à granules de carbone","Directivité":"Cardioïde","Connectique":"XLR 3 points · sortie symétrique","Alimentation":"Fantôme 48 V","Bande":"50 Hz–10 kHz selon le fabricant"}', 'https://wpclone.placidaudio.com/products/ru-80/', '[{"label":"Caractéristiques et FAQ fabricant","url":"https://wpclone.placidaudio.com/products/ru-80/"},{"label":"Test de Rob Tavaglione — Mix Online, 29 octobre 2026","url":"https://www.mixonline.com/technology/reviews/microphones/placid-audio-carbonphone-ru-80-a-mix-mini-review"}]', '/assets/products/placid-audio-carbonphone-ru-80.jpg', 'Placid Audio', '2026-11-06', '[{"title":"Carbonphone RU-80 : un microphone pour donner du grain aux prises","url":"/actualites/#carbonphone-ru-80-test-2026"}]');
INSERT OR REPLACE INTO guides (id, title, intro, sections) VALUES ('choisir-interface', 'Choisir une interface audio', 'Commencez par les sources que vous enregistrez simultanément.', '[["Comptez les entrées nécessaires","Une entrée micro sert une source. Pour une voix et une guitare en même temps, prévoyez les entrées et préamplis correspondants. Une prise instrument requiert une entrée adaptée ou une boîte de direct."],["Vérifiez votre ordinateur","Comparez le protocole de connexion, les ports et la version du système avec la documentation du fabricant. La forme USB-C ne garantit pas à elle seule la compatibilité Thunderbolt."],["Pensez aux sorties","Distinguez sorties ligne, sorties casque et routage indépendant. Prévoyez une marge pour les besoins identifiés, sans confondre nombre de prises et canaux utilisables simultanément."]]');
INSERT OR REPLACE INTO guides (id, title, intro, sections) VALUES ('choisir-monitoring', 'Choisir ses enceintes de monitoring', 'L’espace et le placement font partie du système d’écoute.', '[["Adaptez le format","Considérez la distance d’écoute, la place disponible et le niveau nécessaire. Un haut-parleur plus grand ne corrige pas une pièce résonnante."],["Soignez la disposition","Recherchez une installation symétrique et une hauteur cohérente avec vos oreilles. Respectez les indications du fabricant concernant les murs et les évents."],["Contrôlez la chaîne","Vérifiez les sorties de l’interface, les entrées des enceintes et les câbles. Une enceinte passive nécessite une amplification appropriée. Vérifiez si le prix concerne une unité ou une paire."]]');
INSERT OR REPLACE INTO guides (id, title, intro, sections) VALUES ('casque-ouvert-ferme', 'Casque ouvert ou fermé', 'Choisissez selon le lieu et l’étape de travail.', '[["Pendant la prise","Une conception fermée limite les fuites vers le micro. L’isolation réelle et le confort varient selon le modèle et l’ajustement."],["Pendant le mixage","Un casque ouvert laisse passer le son dans les deux sens : réservez-le à un espace calme. Alternez les écoutes pour repérer les déséquilibres."],["Vérifiez l’amplification","L’impédance seule ne permet pas de prédire le niveau disponible. Consultez aussi la sensibilité et les caractéristiques de la sortie casque."]]');
INSERT OR REPLACE INTO guides (id, title, intro, sections) VALUES ('connexions-studio', 'Comprendre les connexions d’un studio', 'Identifiez le signal avant de choisir le câble.', '[["Analogique","Micro, instrument et ligne sont des niveaux différents. Un connecteur identique ne signifie pas un signal identique. Vérifiez aussi liaison symétrique ou asymétrique."],["Numérique","ADAT, S/PDIF et audio réseau ne sont pas interchangeables. Les canaux disponibles peuvent dépendre de la fréquence d’échantillonnage."],["Synchronisation","Plusieurs appareils numériques doivent partager une référence d’horloge cohérente. Définissez le maître et les appareils synchronisés selon leurs notices."]]');
INSERT OR REPLACE INTO guides (id, title, intro, sections) VALUES ('traitement-acoustique', 'Débuter le traitement acoustique', 'Écoutez et mesurez avant d’acheter des panneaux.', '[["Placement d’abord","Déplacez l’écoute et les enceintes avec méthode avant de choisir un traitement. Notez les changements afin de comparer les positions."],["Absorption et diffusion","Ces solutions répondent à des problèmes différents. La performance d’un absorbant dépend notamment de sa construction, son épaisseur et son installation."],["Traitement et isolation","Améliorer l’écoute dans une pièce ne garantit pas de réduire le bruit transmis aux voisins. Pour un diagnostic fiable, faites étudier la pièce et ses contraintes."]]');
INSERT OR REPLACE INTO guides (id, title, intro, sections) VALUES ('premier-home-studio', 'Construire une première configuration home studio', 'Concevez une chaîne simple autour d’un usage précis.', '[["Définissez votre session","Voix seule, instruments, production MIDI ou podcast : chaque scénario demande un nombre différent d’entrées et de retours casque."],["Listez la chaîne complète","Ordinateur compatible, logiciel, interface, écoute et câbles forment la base. Ajoutez micro, pied et filtre anti-pop si vous captez une voix."],["Validez avant achat","Vérifiez les systèmes pris en charge, protocoles, alimentations, câbles inclus et licences. Essayez une courte session complète avant un enregistrement important."]]');
