INSERT OR REPLACE INTO news (id, title, category, date, summary, source, source_name, image, image_credit, image_alt, tags, product_ids, section) VALUES ('carbonphone-ru-80-test-2026', 'Carbonphone RU-80 : un microphone pour donner du grain aux prises', 'TEST EXTERNE · MICROPHONES', '2026-10-29', 'Dans son essai pour Mix Online, Rob Tavaglione explore le caractère saturé de ce microphone à carbone sur voix, guitare et batterie. Il apprécie sa texture, tout en signalant une réponse difficile sur les sons très faibles et un écrasement marqué sur les sons très forts. Un outil de coloration dont le comportement dépend du niveau reçu.', 'https://www.mixonline.com/technology/reviews/microphones/placid-audio-carbonphone-ru-80-a-mix-mini-review', 'Mix Online', '/assets/products/placid-audio-carbonphone-ru-80.jpg', 'Photo officielle · Placid Audio', 'Microphone Placid Audio Carbonphone RU-80', '["Microphones"]', '["placid-audio-carbonphone-ru-80"]', 'Tests');
INSERT OR REPLACE INTO news (id, title, category, date, summary, source, source_name, image, image_credit, image_alt, tags, product_ids, section) VALUES ('izotope-photon-2026', 'Photon : séparer les sources et nettoyer les dialogues en local', 'ANNONCE FABRICANT · RESTAURATION', '2026-11-03', 'iZotope présente Photon, une application autonome également intégrable aux stations audio compatibles ARA2. Ses modèles séparent musique, voix ou intervenants et traitent différents bruits de prise de son. Les calculs s’effectuent localement sur le processeur graphique. Les prérequis matériels sont à vérifier avant installation. Il s’agit d’une annonce du fabricant.', 'https://www.izotope.com/community/blog/introducing-photon', 'iZotope', '/assets/products/izotope-photon.png', 'Visuel officiel · iZotope', 'Interface iZotope Photon en mode Music 4 Stems', '["Logiciels"]', '["izotope-photon"]', 'Technique');
INSERT OR REPLACE INTO news (id, title, category, date, summary, source, source_name, image, image_credit, image_alt, tags, product_ids, section) VALUES ('nugen-vislm-3-2026', 'VisLM 3 : suivre le niveau sonore de plusieurs stems', 'ANNONCE PRODUIT · LOGICIELS', '2026-10-29', 'NUGEN fait évoluer son outil de mesure avec une vue regroupant plusieurs stems, des annotations horodatées et des rapports de contrôle qualité exportables. La mesure du rapport entre niveau global et dialogue complète les outils destinés aux livraisons audiovisuelles. Mix Online relaie cette annonce du fabricant ; il ne s’agit pas d’un test.', 'https://www.mixonline.com/technology/news-products/nugen-audio-launches-next-gen-vislm-3', 'Mix Online', '/assets/products/nugen-vislm-3.jpg', 'Visuel officiel · NUGEN Audio', 'Interface de NUGEN Audio VisLM 3', '["Logiciels"]', '["nugen-vislm-3"]', 'Technique');
INSERT OR REPLACE INTO news (id, title, category, date, summary, source, source_name, image, image_credit, image_alt, tags, product_ids, section) VALUES ('hedd-type-40-2026', 'HEDD TYPE 40 : une écoute principale qui évolue avec le studio', 'ANNONCE PRODUIT · MONITORING', '2026-10-29', 'HEDD présente une plateforme modulaire associant le moniteur TYPE 40 Main aux extensions de grave XTD. La configuration permet de choisir entre rayonnement frontal et contrôle cardioïde, avec gestion par HEDD CTRL. Le niveau disponible et la directivité varient selon les modules installés. Présentation fabricant relayée par ProSoundWeb, sans essai indépendant.', 'https://www.prosoundweb.com/hedd-audio-introduces-new-type-40-monitoring-platform/', 'ProSoundWeb', '/assets/products/hedd-type-40-main.png', 'Visuel officiel · HEDD Audio', 'Paire de moniteurs HEDD TYPE 40 Main', '["Monitoring"]', '["hedd-type-40-main","hedd-type-40-xtd"]', 'Technique');
INSERT OR REPLACE INTO news (id, title, category, date, summary, source, source_name, image, image_credit, image_alt, tags, product_ids, section) VALUES ('softube-console-1-compact-test', 'Console 1 Compact : le contrôle tactile du mixage à l’épreuve', 'TEST EXTERNE · CONTRÔLEURS', '2026-10-28', 'Dans leur test pour Audiofanzine, Manuel et Dimitri de Studios Megaphone apprécient le format réduit et les possibilités de traitement de Console 1 Compact. Ils soulignent toutefois une navigation parfois complexe entre les pages et des fonctions manquantes pour certains plugins externes. Leur bilan invite à évaluer l’ergonomie selon sa façon de mixer.', 'https://fr.audiofanzine.com/console-midi/softube/console-1-compact/editorial/tests/test-du-console-1-compact-de-softube.html', 'Audiofanzine', '/assets/products/softube-console-1-compact.jpg', 'Visuel officiel · Softube', 'Surface Softube Console 1 Compact', '["Contrôleurs"]', '["softube-console-1-compact"]', 'Tests');
INSERT OR REPLACE INTO news (id, title, category, date, summary, source, source_name, image, image_credit, image_alt, tags, product_ids, section) VALUES ('kazrog-vac-rac-tsl-2026', 'Vac Rac TSL : la compression optique à tubes en plug-in', 'ANNONCE PRODUIT · LOGICIELS', '2026-10-28', 'Kazrog transpose le compresseur-limiteur Inward Connections dans un plug-in développé avec Steve Firlotte. Le traitement associe liaison stéréo, mode mid/side, filtres de détection et mélange parallèle. La commande THD permet de doser la coloration des étages à tubes modélisés. Il s’agit d’une présentation du produit, sans essai d’écoute.', 'https://fr.audiofanzine.com/compresseur-logiciel/kazrog/vac-rac-tsl/news/a.play%2Cn.83361.html', 'Audiofanzine', '/assets/products/kazrog-vac-rac-tsl.png', 'Visuel officiel · Kazrog', 'Interface du plug-in Kazrog Vac Rac TSL', '["Logiciels"]', '["kazrog-vac-rac-tsl"]', 'Technique');
INSERT OR REPLACE INTO news (id, title, category, date, summary, source, source_name, image, image_credit, image_alt, tags, product_ids, section) VALUES ('pulsar-digitape-2026', 'DigiTape : deux approches de la saturation numérique', 'ANNONCE FABRICANT · LOGICIELS', '2026-10-27', 'Pulsar Audio propose deux modes de coloration : Contour travaille les aigus et les transitoires, tandis que Grain sature les bandes graves et médiums. Les réglages Drive, Brightness et Mix permettent de doser le traitement. Le logiciel est proposé gratuitement après un questionnaire ; son activation nécessite un compte iLok.', 'https://pulsar.audio/digitape/', 'Pulsar Audio', '/assets/products/pulsar-audio-digitape.jpg', 'Visuel officiel · Pulsar Audio', 'Interface du plug-in Pulsar Audio DigiTape', '["Logiciels"]', '["pulsar-audio-digitape"]', 'Technique');
INSERT OR REPLACE INTO news (id, title, category, date, summary, source, source_name, image, image_credit, image_alt, tags, product_ids, section) VALUES ('focusrite-control-2', 'Focusrite Control 2 : le pilotage MIDI rejoint le studio', 'MISE À JOUR · INTERFACES', '2026-10-20', 'Focusrite ajoute le contrôle MIDI et fait évoluer Auto Gain, le Loopback et le gain de certaines entrées ligne. Les fonctions disponibles dépendent de l’interface : l’annonce précise les modèles concernés.', 'https://focusrite.com/articles/focusrite-control-2-updates-midi-control-auto-gain-improvements-and-more/', 'Focusrite', 'https://cdn11.bigcommerce.com/s-7exlzlf13h/product_images/uploaded_images/fc2-q3-news-story-thumbnail.png', 'Visuel officiel · Focusrite', 'Interface du logiciel Focusrite Control 2', '["Interfaces","Logiciels"]', '["focusrite-control-2","focusrite-scarlett-2i2-4th","focusrite-scarlett-18i20-4th"]', 'Technique');
INSERT OR REPLACE INTO news (id, title, category, date, summary, source, source_name, image, image_credit, image_alt, tags, product_ids, section) VALUES ('adam-control', 'Sub PRO et ADAM Control : gérer le grave dans une écoute de studio', 'MONITORING · CALIBRATION', '2026-10-08', 'ADAM Audio associe ses nouveaux caissons Sub8 PRO et Sub10 PRO à une plateforme de gestion et de calibration par Ethernet. La marque documente des réglages manuels ainsi que l’intégration de filtres SoundID Reference.', 'https://www.adam-audio.com/en/news/industry/introducing-the-sub8-pro-and-sub10-pro/', 'ADAM Audio', 'https://www.adam-audio.com/content/uploads/2026/10/adam-audio-sub8-pro-sub10-pro-subwoofer-lifestyle-image.jpeg', 'Visuel officiel · ADAM Audio', 'Caissons ADAM Audio Sub8 PRO et Sub10 PRO en studio', '["Monitoring"]', '["adam-sub8-pro","adam-sub10-pro","adam-control","sonarworks-soundid-reference"]', 'Technique');
INSERT OR REPLACE INTO news (id, title, category, date, summary, source, source_name, image, image_credit, image_alt, tags, product_ids, section) VALUES ('immersive-bundles', 'A Series Immersive Bundles : des ensembles pour le mixage immersif', 'STUDIO · AUDIO IMMERSIF', '2026-03-01', 'ADAM Audio présente trois ensembles d’enceintes A Series pour les studios de musique et de postproduction souhaitant travailler en 7.1.4. Le choix du caisson et l’adaptation à la pièce restent à étudier séparément.', 'https://www.adam-audio.com/en/news/industry/a-series-immersive-bundles/', 'ADAM Audio', 'https://www.adam-audio.com/content/uploads/2026/02/Immersive_Audio_Setup-A-Serie-1024x683.png', 'Visuel officiel · ADAM Audio', 'Installation immersive ADAM Audio A Series', '["Monitoring","Immersif"]', '["adam-a-series-satellite-bundle","adam-a-series-complete-bundle","adam-a-series-professional-bundle"]', 'Technique');
INSERT OR REPLACE INTO releases (id, title, family, date, summary, source, source_name, image, product_ids) VALUES ('h715', 'H715 Reference', 'Casques de studio', '2026-10-22', 'Casque ouvert de référence · 150 Ω · mixage et mastering', 'https://www.adam-audio.com/en/news/industry/introducing-the-h715-reference/', 'ADAM Audio', 'https://www.adam-audio.com/content/uploads/2026/10/adam-audio-h715-reference-studio-headphones-news-post.jpg', '["adam-h715-reference"]');
INSERT OR REPLACE INTO releases (id, title, family, date, summary, source, source_name, image, product_ids) VALUES ('altitude', 'Altitude Harmony', 'Logiciels de studio', '2026-10-22', 'Plugin de production vocale · harmonies et correction de hauteur', 'https://focusrite.com/articles/focusrite-and-klevgrand-launch-altitude-harmony/', 'Focusrite / Klevgrand', 'https://cdn11.bigcommerce.com/s-7exlzlf13h/product_images/uploaded_images/news-story-thumbnails-980x302-alt2.png', '["focusrite-klevgrand-altitude-harmony"]');
