INSERT OR REPLACE INTO releases (id, title, family, date, summary, source, source_name, image, product_ids) VALUES ('ssl', 'UMD192', 'Interfaces audio', '2026-01-20', 'Interface professionnelle · USB, MADI et Dante · studio et broadcast', 'https://solidstatelogic.com/media/ise-2026-solid-state-logic-to-debut-the-new-umd192-interface,-designed-to-excel-in-live-sound,-broadcast,-and-high-spec-studio-environments', 'Solid State Logic', 'https://solidstatelogic.com/assets/components/phpthumbof/cache/SSL%20UMD%20192%20SSL%20Live%20Hero%202.2ee44ebff6b318f2570576ad0d281e44.jpg', '["ssl-umd192"]');
INSERT OR REPLACE INTO events (id, title, kind, start, end, region, format, location, venue, summary, practical, source, source_name, image) VALUES ('satis-2026', 'SATIS 2026', 'PRODUCTION · POSTPRODUCTION · AUDIO', '2026-11-04', '2026-11-05', 'France', 'Salon', 'La Plaine Saint-Denis · France', 'Docks de Paris', 'Le rendez-vous des professionnels de l’image et du son : équipements, démonstrations et conférences autour de la production, de la postproduction et du broadcast.', '"Accréditation et programme à consulter sur le site de l’organisateur. Vérifiez les sessions audio et les exposants avant de préparer votre visite."', 'https://satis-expo.com/fr/', 'SATIS', 'https://satis-expo.com/wp-content/uploads/sites/5/2023/10/SATIS-noir-copie-1024x237.png');
INSERT OR REPLACE INTO events (id, title, kind, start, end, region, format, location, venue, summary, practical, source, source_name, image) VALUES ('namm-2027', 'The NAMM Show 2027', 'MUSIQUE · AUDIO PRO · TECHNOLOGIES', '2027-01-26', '2027-01-30', 'International', 'Salon', 'Anaheim · États-Unis', 'Anaheim Convention Center', 'Instruments, technologies musicales et matériel audio professionnel : rencontres avec les fabricants, découverte des équipements et sessions destinées aux métiers du son.', '"Événements du 26 au 30 janvier ; exposition du 28 au 30 janvier 2027. Conditions d’accès, inscription et programme à vérifier auprès du NAMM."', 'https://www.namm.org/node/75', 'NAMM', 'https://www.namm.org/sites/default/files/styles/promo/public/2026-02/ns26_24_131734_1331_c.jpg?itok=iyHbMxib');
INSERT OR REPLACE INTO events (id, title, kind, start, end, region, format, location, venue, summary, practical, source, source_name, image) VALUES ('ise-2027', 'ISE 2027', 'AUDIO PROFESSIONNEL · INTÉGRATION · BROADCAST', '2027-02-02', '2027-02-05', 'International', 'Salon', 'Barcelone · Espagne', 'Fira de Barcelona · Gran Via', 'Un salon de l’intégration audiovisuelle avec des espaces consacrés à l’audio professionnel et aux solutions broadcast. Une entrée complémentaire pour les installations et les régies.', '"Du 2 au 5 février 2027. Programme, exposants audio, accréditation et horaires sur le site officiel."', 'https://www.iseurope.org/', 'ISE', 'https://cdn.asp.events/CLIENT_Integrat_169E7B04_E6F3_39F6_8BE4DB27C54F731E/sites/ise-2027/media/2027/reg-is-open.jpg/fit-in/1200x630/filters:no_upscale()');
INSERT OR REPLACE INTO tools (id, name, status, text, steps, note, icon, position) VALUES ('pad', 'Phone control pad', 'Concept', 'Turn your phone into a customizable button pad for the actions you repeat most while producing.', '["Open the pad on your phone.","Pair it with your computer.","Assign buttons to your own actions."]', 'Needs research: depends on how it can talk to your production software.', 'phone', 0);
INSERT OR REPLACE INTO tools (id, name, status, text, steps, note, icon, position) VALUES ('stems', 'Stem splitter', 'Concept', 'Separate a track into parts such as vocals, drums and bass.', '["Upload an audio file.","Wait while it is processed.","Download the separate parts."]', 'Needs heavy processing, so cost and usage limits are still open.', 'split', 1);
INSERT OR REPLACE INTO tools (id, name, status, text, steps, note, icon, position) VALUES ('styles', 'Style explorer', 'Concept', 'Browse music styles with their typical tempo, instruments and sound references.', '["Pick a style.","See typical tempo and instruments.","Jump to matching gear in Equipment."]', 'The content has to be written and checked before launch.', 'music', 2);
INSERT OR REPLACE INTO tools (id, name, status, text, steps, note, icon, position) VALUES ('labels', 'Equipment labels', 'Planned', 'Print QR labels for your gear and scan them to open the item in My Studio.', '["Pick items in My Studio.","Print the label sheet on any printer.","Scan a label to open the item."]', 'Closest to ready: it uses the inventory that already exists.', 'qr', 3);
